CREATE TABLE IF NOT EXISTS schema_migrations (id TEXT PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS services (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL, duration INTEGER NOT NULL CHECK(duration>0 AND duration<=480), active INTEGER NOT NULL CHECK(active IN (0,1)) DEFAULT 1);
CREATE TABLE IF NOT EXISTS availability_rules (id TEXT PRIMARY KEY, weekday INTEGER NOT NULL CHECK(weekday BETWEEN 1 AND 7), start_time TEXT NOT NULL, end_time TEXT NOT NULL CHECK(end_time>start_time), timezone TEXT NOT NULL CHECK(timezone='Europe/Madrid'), resource TEXT NOT NULL CHECK(resource='silla-1'), UNIQUE(weekday,resource));
CREATE TABLE IF NOT EXISTS bookings (id TEXT PRIMARY KEY, service_id TEXT NOT NULL REFERENCES services(id), resource TEXT NOT NULL CHECK(resource='silla-1'), name TEXT NOT NULL CHECK(length(name) BETWEEN 2 AND 100), email TEXT NOT NULL CHECK(length(email) BETWEEN 3 AND 254), start_utc TEXT NOT NULL, end_utc TEXT NOT NULL CHECK(end_utc>start_utc), status TEXT NOT NULL CHECK(status='confirmed') DEFAULT 'confirmed', idempotency_key TEXT NOT NULL UNIQUE, payload_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS bookings_resource_time ON bookings(resource,start_utc,end_utc);
CREATE TRIGGER IF NOT EXISTS bookings_no_overlap BEFORE INSERT ON bookings WHEN EXISTS (SELECT 1 FROM bookings WHERE resource=NEW.resource AND start_utc<NEW.end_utc AND end_utc>NEW.start_utc) BEGIN SELECT RAISE(ABORT,'booking_overlap'); END;
CREATE TRIGGER IF NOT EXISTS bookings_no_overlap_update BEFORE UPDATE OF start_utc,end_utc,resource ON bookings WHEN EXISTS (SELECT 1 FROM bookings WHERE id<>NEW.id AND resource=NEW.resource AND start_utc<NEW.end_utc AND end_utc>NEW.start_utc) BEGIN SELECT RAISE(ABORT,'booking_overlap'); END;
